const PROJECT_THUMBS = FALLBACK_IMAGES.projects;

function attachFallback(image, dataUri) {
  image.addEventListener("error", function handleError() {
    image.removeEventListener("error", handleError);
    image.src = dataUri;
  });
}

function applyFallbacks() {
  document.querySelectorAll("[data-avatar]").forEach((image) => {
    attachFallback(image, FALLBACK_IMAGES.avatar);
  });

  document.querySelectorAll("[data-thumb]").forEach((image) => {
    const key = image.dataset.thumb;
    const dataUri = PROJECT_THUMBS[key];

    if (!dataUri) {
      console.warn("Fallback thumbnail tidak ditemukan untuk:", key);
      return;
    }

    attachFallback(image, dataUri);
  });
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", applyFallbacks);
} else {
  applyFallbacks();
}

window.FALLBACK_IMAGES = FALLBACK_IMAGES;
window.PROJECT_THUMBS = PROJECT_THUMBS;
